python3 - <<'PY'
import msgpack,io,inspect,json
print('msgpack_version',msgpack.__version__)
print('Unpacker signature',inspect.signature(msgpack.Unpacker))
print('Unpacker doc', (msgpack.Unpacker.__doc__ or '')[:1200])
b=open('inputs/chall/unknown.data','rb').read()
def pair_hook(pairs):return ('__map__',pairs)
u=msgpack.Unpacker(io.BytesIO(b),raw=False,strict_map_key=False,object_pairs_hook=pair_hook)
def brief(x,path='root',d=0):
 if d>12:return {'type':type(x).__name__,'depth_cap':True}
 if isinstance(x,tuple) and len(x)==2 and x[0]=='__map__':
  arr=[]
  for k,v in x[1][:80]:
   key=k.decode('utf8','replace') if isinstance(k,bytes) else str(k)
   arr.append({'key':key[:100],'value':brief(v,path+'/'+key.lower(),d+1)})
  return {'type':'map','n':len(x[1]),'items':arr}
 if isinstance(x,list):return {'type':'array','n':len(x),'items':[brief(y,path+'[]',d+1) for y in x[:80]]}
 if isinstance(x,bytes):return {'type':'bytes','n':len(x)}
 if isinstance(x,str):
  p=path.lower()
  if ('contact' in p or 'recipient' in p) and any(w in p for w in ('name','person','identity','display')) and not any(w in p for w in ('key','secret','password','email','token')):
   return {'type':'str','n':len(x),'value':x[:120]}
  return {'type':'str','n':len(x),'value':'[suppressed]'}
 if x is None or isinstance(x,(bool,int,float)):return {'type':type(x).__name__,'value':x}
 return {'type':type(x).__name__}
items=[]
try:
 for i,x in enumerate(u):
  items.append({'index':i,'end_offset':u.tell(),'summary':brief(x)})
  if i>=19:break
 print('unpack_count',len(items),'next_offset',u.tell())
 print(json.dumps(items,ensure_ascii=True))
except Exception as e:
 print('stream_error',type(e).__name__,str(e),'at_offset',u.tell(),'decoded_before_error',len(items))
 print(json.dumps(items,ensure_ascii=True))
